# Six drafted questions were left out to keep the paper at 100 and avoid overlap with the essay page.
DROP = ['Hàm kích hoạt nào được dùng trong các mô hình BERT', 'Trong RNN, các tham số được dùng thế nào',
        'Khi nào nên dùng mô hình đơn giản', 'Theo Rules of ML của Google', 'Biện pháp nào giúp giảm việc LLM',
        'Grad-CAM được dùng để làm gì']
NEW = [q for q in NEW if not any(q['q'].startswith(d) for d in DROP)]


def _rebalance(qs):
    """Swap in the length-balanced options from de03_options (correct option first)."""
    from de03_options import OPTIONS
    used = set()
    qs = [dict(q) for q in qs]  # pool dicts are shared with L01; do not change them in place
    for q in qs:
        for key, opts in OPTIONS.items():
            if q['shuffle'] and q['q'].startswith(key):
                assert q['answer'] == 0 and key not in used, key
                q['options'] = list(opts)
                used.add(key)
    missing = set(OPTIONS) - used
    assert not missing, missing
    return qs


QS = _rebalance(HF2 + [POOL[i] for i in POOL_IDX] + NEW)
